+"""Small in-process NVRTC launcher. Kernels use the current PyTorch stream."""
+import ctypes as ct
+from functools import lru_cache
+
+import torch
+
+
+@lru_cache(None)
+def _libraries():
+    rtc = ct.CDLL("libnvrtc.so.12")
+    driver = ct.CDLL("libcuda.so.1")
+    return rtc, driver
+
+
+def _check(status, operation):
+    if status:
+        raise RuntimeError(f"{operation} failed with status {status}")
+
+
+@lru_cache(None)
+def _compile(source, arch):
+    rtc, _ = _libraries()
+    program = ct.c_void_p()
+    _check(rtc.nvrtcCreateProgram(ct.byref(program), source.encode(), b"dbscan.cu",
+                                  0, None, None), "nvrtcCreateProgram")
+    try:
+        options = (ct.c_char_p * 2)(f"--gpu-architecture=compute_{arch}".encode(),
+                                    b"--std=c++17")
+        status = rtc.nvrtcCompileProgram(program, 2, options)
+        size = ct.c_size_t()
+        if status:
+            rtc.nvrtcGetProgramLogSize(program, ct.byref(size))
+            log = ct.create_string_buffer(size.value)
+            rtc.nvrtcGetProgramLog(program, log)
+            raise RuntimeError(log.value.decode())
+        _check(rtc.nvrtcGetPTXSize(program, ct.byref(size)), "nvrtcGetPTXSize")
+        ptx = ct.create_string_buffer(size.value)
+        _check(rtc.nvrtcGetPTX(program, ptx), "nvrtcGetPTX")
+        return ptx
+    finally:
+        rtc.nvrtcDestroyProgram(ct.byref(program))
+
+
+@lru_cache(None)
+def _module(source, device):
+    _, driver = _libraries()
+    major, minor = torch.cuda.get_device_capability(device)
+    module = ct.c_void_p()
+    ptx = _compile(source, 10 * major + minor)
+    _check(driver.cuModuleLoadData(ct.byref(module), ptx), "cuModuleLoadData")
+    return module
+
+
+@lru_cache(None)
+def _function(source, device, name):
+    _, driver = _libraries()
+    func = ct.c_void_p()
+    _check(driver.cuModuleGetFunction(ct.byref(func), _module(source, device),
+                                      name.encode()), "cuModuleGetFunction")
+    return func
+
+
+class _Node(ct.Structure):
+    _fields_ = [
+        ("func", ct.c_void_p),
+        ("grid", ct.c_uint * 3),
+        ("block", ct.c_uint * 3),
+        ("shared", ct.c_uint),
+        ("params", ct.POINTER(ct.c_void_p)),
+        ("extra", ct.POINTER(ct.c_void_p)),
+    ]
+
+
+class KernelGraph:
+    """A per-stream launch plan with private intermediate storage.
+
+    The first node takes the current input and a fresh output as its first two
+    arguments. Updating that node binds the graph to a single DBSCAN call.
+    """
+
+    def __init__(self, source, device, stream):
+        import threading
+
+        self.source = source
+        self.device = device
+        self.stream = ct.c_void_p(stream)
+        self.driver = _libraries()[1]
+        self.graph = ct.c_void_p()
+        self.executable = ct.c_void_p()
+        self.last = ct.c_void_p()
+        self.storage = []
+        self.nodes = {}
+        self.lock = threading.Lock()
+        _check(self.driver.cuGraphCreate(ct.byref(self.graph), 0), "cuGraphCreate")
+
+    def add(self, name, grid, block, *args, after=None):
+        values = []
+        for arg in args:
+            if arg is None:
+                values.append(ct.c_void_p())
+            elif isinstance(arg, int):
+                values.append(ct.c_int(arg))
+            elif isinstance(arg, float):
+                values.append(ct.c_float(arg))
+            else:
+                values.append(ct.c_void_p(arg.data_ptr()))
+                self.storage.append(arg)
+        params = (ct.c_void_p * len(args))(*(ct.addressof(v) for v in values))
+        node = _Node(_function(self.source, self.device, name),
+                     (ct.c_uint*3)(grid,1,1), (ct.c_uint*3)(block,1,1), 0, params, None)
+        handle = ct.c_void_p()
+        parents = [self.nodes[key] for key in after] if after else [self.last] if self.last else []
+        deps = (ct.c_void_p * len(parents))(*parents) if parents else None
+        _check(self.driver.cuGraphAddKernelNode(ct.byref(handle), self.graph, deps,
+                                                ct.c_size_t(len(parents)), ct.byref(node)),
+               name)
+        if not self.last:
+            self.first, self.node, self.values = handle, node, values
+        self.nodes[name] = self.last = handle
+
+    def build(self):
+        _check(self.driver.cuGraphInstantiateWithFlags(ct.byref(self.executable),
+                                                      self.graph, ct.c_ulonglong(0)),
+               "cuGraphInstantiateWithFlags")
+        return self
+
+    def launch(self, x, out):
+        with self.lock:
+            self.values[0].value = x.data_ptr()
+            self.values[1].value = out.data_ptr()
+            _check(self.driver.cuGraphExecKernelNodeSetParams(self.executable, self.first,
+                                                              ct.byref(self.node)),
+                   "cuGraphExecKernelNodeSetParams")
+            _check(self.driver.cuGraphLaunch(self.executable, self.stream), "cuGraphLaunch")
+
+    def __del__(self):
+        if self.executable:
+            self.driver.cuGraphExecDestroy(self.executable)
+        if self.graph:
+            self.driver.cuGraphDestroy(self.graph)
